class PinLock:
    def __init__(self, pin):
        self.pin=pin
        self.attempts=0
    def check_code(self, candidate):
        if not isinstance(candidate,str) or len(candidate)!=4 or any(c not in '0123456789' for c in candidate):
            raise ValueError('invalid pin')
        self.attempts+=1
        return candidate==self.pin
